//! Rhyme detection for song lyrics, built on the CMU Pronouncing Dictionary
//! (`assets/rhymes.txt`, generated by `assets/make_rhymes.py`, licence in `assets/CMUDICT-LICENSE`).
//!
//! A word's *rhyme tail* is its phonemes from the last stressed vowel to the end
//! (`mine` and `fine` are both `AY N`). Words with equal tails rhyme; end-of-line words
//! that find no partner are then tried for a loose "slant" rhyme.

use std::collections::HashMap;
use std::sync::OnceLock;

/// Number of colour groups the UI has; every `Mark::group` is below this.
pub const GROUPS: usize = 8;

/// A rhyming word: byte range inside its line, plus its colour-group index
/// (0 = the most frequent rhyme sound in the verse).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Mark {
    pub start: usize,
    pub end: usize,
    pub group: usize,
}

static DATA: &str = include_str!("../assets/rhymes.txt");

/// File layout: tail count, that many tail lines, then sorted `word code` lines
/// (code = base-36 index into the tails).
struct Dict {
    tails: Vec<&'static str>,
    words: Vec<&'static str>,
}

fn dict() -> &'static Dict {
    static D: OnceLock<Dict> = OnceLock::new();
    D.get_or_init(|| {
        let mut it = DATA.lines();
        let n: usize = it.next().and_then(|l| l.parse().ok()).unwrap_or(0);
        let tails = it.by_ref().take(n).collect();
        Dict { tails, words: it.collect() }
    })
}

fn lookup(word: &str) -> Option<&'static str> {
    let d = dict();
    let i = d
        .words
        .binary_search_by(|l| l.split(' ').next().unwrap_or("").cmp(word))
        .ok()?;
    let code = d.words[i].split(' ').nth(1)?;
    d.tails.get(usize::from_str_radix(code, 36).ok()?).copied()
}

/// Words that are never *internal* rhyme candidates (they still count at a line end).
const STOP: &[&str] = &[
    "the", "a", "an", "i", "you", "me", "my", "we", "to", "in", "it", "is", "and", "of", "on",
    "for", "that", "this", "with", "but", "so", "up", "no", "oh", "yeah", "uh", "ah", "ay", "ooh",
    "hey", "he", "she", "they", "them", "us", "our", "your", "his", "her", "its", "at", "as",
    "be", "am", "are", "was", "were", "do", "did", "have", "has", "had", "or", "if", "then",
    "than", "not", "just", "all", "out", "off", "from", "by", "can", "will", "got", "get",
    "like", "what", "who", "how", "why", "when", "where", "there", "here", "too", "now",
    "i'm", "i'll", "i've", "i'd", "it's", "that's", "don't", "can't", "ain't", "you're",
    "we're", "they're", "he's", "she's", "what's", "let's", "gonna", "wanna", "gotta",
    "ya", "em", "cause", "uh-huh", "yo", "ha", "la", "na", "da",
];

struct Tok {
    start: usize,
    end: usize,
    text: String,
    paren: bool,
}

/// Letters plus apostrophes that follow a letter ("don't", "gettin'").
/// Anything inside `( )` or `[ ]` is flagged `paren`.
fn tokenize(line: &str) -> Vec<Tok> {
    let ch: Vec<(usize, char)> = line.char_indices().collect();
    let (mut toks, mut depth, mut i) = (Vec::new(), 0i32, 0);
    while i < ch.len() {
        let c = ch[i].1;
        match c {
            '(' | '[' => depth += 1,
            ')' | ']' => depth = (depth - 1).max(0),
            _ if c.is_alphabetic() => {
                let mut j = i + 1;
                while j < ch.len() {
                    let cj = ch[j].1;
                    let apos = (cj == '\'' || cj == '’') && ch[j - 1].1.is_alphabetic();
                    if cj.is_alphabetic() || apos {
                        j += 1;
                    } else {
                        break;
                    }
                }
                let (start, end) = (ch[i].0, ch.get(j).map_or(line.len(), |x| x.0));
                let text = line[start..end].replace('’', "'").to_lowercase();
                toks.push(Tok { start, end, text, paren: depth > 0 });
                i = j;
                continue;
            }
            _ => {}
        }
        i += 1;
    }
    toks
}

/// Crude fallback for words missing from the dictionary: last vowel group plus the
/// letters after it, prefixed with `~` so it only ever equals another guessed tail.
fn spelling_tail(w: &str) -> Option<String> {
    let mut cs: Vec<char> = w.chars().filter(|c| c.is_alphabetic()).collect();
    if cs.len() < 3 {
        return None;
    }
    if cs.len() > 3 && cs.last() == Some(&'e') {
        cs.pop();
    }
    let vowel = |c: &char| "aeiouy".contains(*c);
    let mut s = cs.iter().rposition(vowel)?;
    while s > 0 && vowel(&cs[s - 1]) {
        s -= 1;
    }
    Some(format!("~{}", cs[s..].iter().collect::<String>()))
}

/// Rhyme-tail key for `w` (lowercase) and whether it came from the dictionary.
/// Tries: exact, dropped-g ("gettin'" -> "getting"), bare, "'s" removed, then spelling.
fn resolve(w: &str, guess: bool) -> Option<(String, bool)> {
    let find = |s: &str| lookup(s).map(str::to_string);
    let dropped_g = w.ends_with("in'");
    let mut hit = find(w);
    if hit.is_none() && dropped_g {
        hit = find(&format!("{}g", w.trim_end_matches('\'')));
    }
    let bare = w.trim_end_matches('\'');
    if hit.is_none() && bare.len() != w.len() && !dropped_g {
        hit = find(bare);
    }
    if hit.is_none() && bare.len() > 3 && bare.ends_with("in") {
        hit = find(&format!("{bare}g"));
    }
    if hit.is_none() {
        if let Some(b) = w.strip_suffix("'s") {
            hit = find(b);
        }
    }
    match hit {
        Some(mut t) => {
            // "-ing" and dropped-g "-in'" should rhyme with each other.
            let drop = dropped_g || (bare.ends_with("in") && !w.ends_with("ing"));
            let mut ph: Vec<&str> = t.split(' ').collect();
            let n = ph.len();
            if n >= 2 && (ph[n - 2..] == ["IH", "NG"] || (drop && ph[n - 2..] == ["AH", "N"])) {
                ph[n - 2..].copy_from_slice(&["IH", "N"]);
                t = ph.join(" ");
            }
            Some((t, true))
        }
        None if guess => spelling_tail(w).map(|t| (t, false)),
        None => None,
    }
}

struct Cand {
    line: usize,
    start: usize,
    end: usize,
    word: String,
    tail: String,
    exact: bool,
    is_end: bool,
}

/// Slant key: the stressed vowel plus whether the trailing consonant is voiceless
/// (P T K F S TH SH CH HH). Everything else (nasals, liquids, voiced stops/fricatives,
/// or no consonant) counts as one voiced class, so mind/fine/high/time (AY + voiced)
/// match loosely while life/light (AY + voiceless) and cat/dog (different vowels) do not.
fn slant_key(tail: &str) -> (&str, bool) {
    let mut ph = tail.split(' ');
    let vowel = ph.next().unwrap_or("");
    let voiceless = matches!(ph.last(), Some("P" | "T" | "K" | "F" | "S" | "TH" | "SH" | "CH" | "HH"));
    (vowel, voiceless)
}

fn distinct(c: &[Cand], idx: &[usize]) -> bool {
    idx.iter().any(|&i| c[i].word != c[idx[0]].word)
}

/// Finds rhymes in one verse (consecutive non-blank lines). Returns one `Vec<Mark>` per
/// input line, sorted by `start`. A verse of identical lines (a repeated hook) gets no marks.
pub fn mark_verse(lines: &[&str]) -> Vec<Vec<Mark>> {
    let mut out = vec![Vec::new(); lines.len()];
    let norm = |l: &str| l.trim().to_lowercase();
    if lines.len() >= 2 && lines.iter().all(|l| norm(l) == norm(lines[0])) {
        return out;
    }

    let mut cands: Vec<Cand> = Vec::new();
    for (li, line) in lines.iter().enumerate() {
        let toks = tokenize(line);
        let end_idx = toks.iter().rposition(|t| !t.paren);
        for (ti, t) in toks.iter().enumerate() {
            let is_end = Some(ti) == end_idx;
            let internal_ok = !STOP.contains(&t.text.as_str());
            if !is_end && !internal_ok {
                continue;
            }
            let Some((tail, exact)) = resolve(&t.text, is_end) else { continue };
            let long = t.text.chars().filter(|c| c.is_alphabetic()).count() >= 3;
            if !is_end && !(tail.contains(' ') || long) {
                continue;
            }
            cands.push(Cand {
                line: li,
                start: t.start,
                end: t.end,
                word: t.text.trim_end_matches('\'').to_string(),
                tail,
                exact,
                is_end,
            });
        }
    }

    // Perfect rhymes: equal tails. Group order = order of first appearance.
    let mut by_tail: HashMap<&str, usize> = HashMap::new();
    let mut groups: Vec<Vec<usize>> = Vec::new();
    for (i, c) in cands.iter().enumerate() {
        let g = *by_tail.entry(c.tail.as_str()).or_insert_with(|| {
            groups.push(Vec::new());
            groups.len() - 1
        });
        groups[g].push(i);
    }
    groups.retain(|g| distinct(&cands, g));

    // Slant rhymes for end words that found no perfect partner.
    let mut taken = vec![false; cands.len()];
    for &i in groups.iter().flatten() {
        taken[i] = true;
    }
    let mut by_slant: HashMap<(&str, bool), usize> = HashMap::new();
    let mut slant: Vec<Vec<usize>> = Vec::new();
    for (i, c) in cands.iter().enumerate() {
        if c.is_end && c.exact && !taken[i] {
            let g = *by_slant.entry(slant_key(&c.tail)).or_insert_with(|| {
                slant.push(Vec::new());
                slant.len() - 1
            });
            slant[g].push(i);
        }
    }
    groups.extend(slant.into_iter().filter(|g| distinct(&cands, g)));

    // Biggest groups get the lowest colour index; ties keep verse order.
    groups.sort_by_key(|g| (std::cmp::Reverse(g.len()), g[0]));
    groups.truncate(GROUPS);
    for (gi, g) in groups.iter().enumerate() {
        for &i in g {
            let c = &cands[i];
            out[c.line].push(Mark { start: c.start, end: c.end, group: gi });
        }
    }
    for l in &mut out {
        l.sort_by_key(|m| m.start);
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn words<'a>(line: &'a str, marks: &[Mark]) -> Vec<&'a str> {
        marks.iter().map(|m| &line[m.start..m.end]).collect()
    }

    #[test]
    fn dictionary_lookup() {
        assert_eq!(lookup("mine"), Some("AY N"));
        assert_eq!(lookup("fine"), Some("AY N"));
        assert_eq!(lookup("zzzzqq"), None);
    }

    #[test]
    fn perfect_end_rhyme() {
        let l = ["I got the world in the palm of mine", "Everything is gonna be just fine"];
        let m = mark_verse(&l);
        assert_eq!(words(l[0], &m[0]), ["mine"]);
        assert_eq!(words(l[1], &m[1]), ["fine"]);
        assert_eq!(m[0][0].group, m[1][0].group);
    }

    #[test]
    fn slant_end_rhyme() {
        let l = ["never gonna change my mind", "everything is feeling fine", "we reach up to the heavens so high"];
        let m = mark_verse(&l);
        assert!(m.iter().all(|x| x.len() == 1), "{m:?}");
        assert_eq!(m[0][0].group, m[1][0].group);
        assert_eq!(m[0][0].group, m[2][0].group);
    }

    #[test]
    fn cat_dog_do_not_rhyme() {
        let l = ["I saw a cat", "I saw a dog"];
        assert!(mark_verse(&l).iter().all(|m| m.is_empty()));
    }

    #[test]
    fn internal_rhyme_in_one_line() {
        let l = ["Fighting through the night with all my might"];
        let m = mark_verse(&l);
        assert_eq!(words(l[0], &m[0]), ["night", "might"]);
    }

    #[test]
    fn adlib_is_not_the_end_word() {
        let l = ["Counting up the cash all night (what else?)", "Everything is looking right (yeah)"];
        let m = mark_verse(&l);
        assert_eq!(words(l[0], &m[0]), ["night"]);
        assert_eq!(words(l[1], &m[1]), ["right"]);
    }

    #[test]
    fn adlib_can_match_internally() {
        let l = ["Got the heat (heat) in the street", "Never gonna lose"];
        let m = mark_verse(&l);
        assert!(words(l[0], &m[0]).contains(&"heat"), "{m:?}");
        assert!(words(l[0], &m[0]).contains(&"street"), "{m:?}");
    }

    #[test]
    fn dropped_g_resolves() {
        let (a, ea) = resolve("gettin'", false).unwrap();
        let (b, eb) = resolve("rappin'", false).unwrap();
        assert!(ea && eb);
        assert_eq!(a, "IH T IH N");
        assert_eq!(b, "AE P IH N");
        let l = ["Livin' life and gettin' paid", "Ridin' round and sittin' in the shade"];
        let m = mark_verse(&l);
        assert!(m.iter().all(|x| !x.is_empty()), "{m:?}");
        let l = ["Every day I'm hustlin' and gettin'", "Never stopping always sittin'"];
        let m = mark_verse(&l);
        assert_eq!(words(l[0], &m[0]), ["gettin'"]);
        assert_eq!(words(l[1], &m[1]), ["sittin'"]);
    }

    #[test]
    fn slang_in_dictionary() {
        assert!(resolve("tryna", false).is_some());
        assert!(resolve("ma", false).is_some());
    }

    #[test]
    fn identical_word_is_not_a_rhyme() {
        let l = ["I walk this road alone", "I walk this road alone"];
        assert!(mark_verse(&l).iter().all(|m| m.is_empty()));
        let l = ["I walk this road alone", "and I feel so alone"];
        assert!(mark_verse(&l).iter().all(|m| m.is_empty()));
        let l = ["I walk this road alone", "and I feel so alone", "cold as a stone"];
        let m = mark_verse(&l);
        assert!(m.iter().all(|x| x.len() == 1), "{m:?}");
    }

    #[test]
    fn repeated_hook_gets_nothing() {
        let l = ["na na na hey", "na na na hey", "Na na na hey"];
        assert!(mark_verse(&l).iter().all(|m| m.is_empty()));
    }

    #[test]
    fn rap_verse() {
        let l = [
            "Woke up in the morning, grindin' on the block",
            "Tryna make a dollar while the whole world's on the clock",
            "Rolling through the city, ma, I'm never gonna stop",
            "Flexin' on the haters with the diamonds on my watch",
        ];
        let m = mark_verse(&l);
        assert_eq!(words(l[0], &m[0]).last(), Some(&"block"));
        assert_eq!(words(l[1], &m[1]).last(), Some(&"clock"));
        assert!(m[0].last().unwrap().group == m[1].last().unwrap().group);
        assert!(m.iter().flatten().all(|k| k.group < GROUPS));
    }

    #[test]
    fn no_panics_on_odd_input() {
        let l = ["", "   ", "...!!!", "(just an adlib)", "日本語 のうた", "café olé olé", "'''", "naïve ’tis don’t", "1234 5678"];
        let m = mark_verse(&l);
        assert_eq!(m.len(), l.len());
        for (line, marks) in l.iter().zip(&m) {
            for k in marks {
                assert!(line.is_char_boundary(k.start) && line.is_char_boundary(k.end));
            }
        }
        assert!(mark_verse(&[]).is_empty());
    }

    #[test]
    fn many_groups_are_capped() {
        let l: Vec<String> = ["cat bat", "dog fog", "sky fly", "night light", "love dove", "moon spoon", "king ring", "hand land", "tree free", "rain pain", "star car"]
            .iter()
            .map(|p| format!("x {p}"))
            .collect();
        let r: Vec<&str> = l.iter().map(|s| s.as_str()).collect();
        let m = mark_verse(&r);
        assert!(m.iter().flatten().all(|k| k.group < GROUPS));
        assert_eq!(m.iter().flatten().map(|k| k.group).max(), Some(GROUPS - 1));
    }
}
